insert into inventory_merch_counts (variant_id, counted_on, counted_at, unit_count, source)
select r.variant_id, m.d, m.d::timestamp + interval '12 hours', c.n, 'import'
from raw r
cross join lateral unnest(r.counts) with ordinality as c(n, i)
join months m on m.i = c.i
where c.n is not null;
